/// One night of sleep (or a nap). A manual log fills bedtime and wake time
/// (plus optional heart data). Health Connect imports fill the stages.
@DataClassName('SleepEntry')
class SleepEntries extends Table {
  IntColumn get id => integer().autoIncrement()();
  DateTimeColumn get bedtime => dateTime()();
  DateTimeColumn get wakeTime => dateTime()();

  IntColumn get deepMinutes => integer().nullable()();
  IntColumn get remMinutes => integer().nullable()();
  IntColumn get lightMinutes => integer().nullable()();

  /// v2: minutes awake during the session (from a watch).
  IntColumn get awakeMinutes => integer().nullable()();

  IntColumn get restingHeartRate => integer().nullable()();
  IntColumn get hrvMs => integer().nullable()();

  /// Morning check-in, 1 (drained) to 5 (fresh).
  IntColumn get mood => integer().nullable()();

  /// 'manual' or 'health_connect'.
  TextColumn get source => text().withDefault(const Constant('manual'))();

  /// v2: habit tag keys joined with commas, e.g. "caffeine,screens".
  TextColumn get tags => text().withDefault(const Constant(''))();

  /// v2: free-text note.
  TextColumn get note => text().nullable()();

  /// v2: true for a daytime nap.
  BoolColumn get isNap => boolean().withDefault(const Constant(false))();

  /// v2: Health Connect session id (avoids duplicate imports).
  TextColumn get externalId => text().nullable()();
}

/// App settings. Always exactly one row, with id 1.
@DataClassName('SettingsRow')
class AppSettings extends Table {
  IntColumn get id => integer().withDefault(const Constant(1))();
  TextColumn get userName => text().withDefault(const Constant('Chauka'))();

  /// Sleep goal in minutes (480 = 8 hours).
  IntColumn get sleepGoalMinutes =>
      integer().withDefault(const Constant(480))();

  /// Bedtime goal as minutes after midnight (1365 = 10:45 PM).
  IntColumn get bedtimeGoalMinutes =>
      integer().withDefault(const Constant(1365))();

  BoolColumn get bedtimeReminder =>
      boolean().withDefault(const Constant(true))();

  /// v2: wake-up goal, minutes after midnight (420 = 7:00 AM).
  IntColumn get wakeGoalMinutes =>
      integer().withDefault(const Constant(420))();

  /// v2: how many minutes before bedtime the wind-down reminder fires.
  IntColumn get windDownMinutes =>
      integer().withDefault(const Constant(30))();

  /// v2: "How did you sleep?" reminder in the morning.
  BoolColumn get morningReminder =>
      boolean().withDefault(const Constant(false))();

  /// v2: false until the user finishes onboarding.
  BoolColumn get onboardingDone =>
      boolean().withDefault(const Constant(false))();

  /// v2: 'system', 'light' or 'dark'.
  TextColumn get themeMode => text().withDefault(const Constant('system'))();

  /// v2: user connected Health Connect.
  BoolColumn get healthConnectEnabled =>
      boolean().withDefault(const Constant(false))();

  /// v2: last successful Health Connect import.
  DateTimeColumn get lastHealthSync => dateTime().nullable()();

  /// v2: last successful cloud backup.
  DateTimeColumn get lastBackupAt => dateTime().nullable()();

  @override
  Set<Column> get primaryKey => {id};
}

